(6259294, 925664, 116631, '<td valign="top">This is practically the same as your entry in another challenge.....</td>', 'This is practically the same as your entry in another challenge.....', '2010-12-22 00:54:31.000000', NULL, 1),
(6259341, 925890, 51051, '<td valign="top">So cute</td>', 'So cute', '2010-12-22 02:52:43.000000', NULL, 1),
(6259519, 925914, 27399, '<td valign="top">Great vision to construct this shot, very creative and well done.</td>', 'Great vision to construct this shot, very creative and well done.', '2010-12-22 08:47:05.000000', NULL, 1),
(6259523, 925903, 27399, '<td valign="top">Good shot and perfectly titled.  Your bottom left corner: don''t see why you kept that instead of cropping it up.  Top left corner I''m sure you left in intentionally, but without context to what it is it distracts from the rest of the image.  Overall, well done, one of the top images in this challenge.</td>', 'Good shot and perfectly titled.  Your bottom left corner: don''t see why you kept that instead of cropping it up.  Top left corner I''m sure you left in intentionally, but without context to what it is it distracts from the rest of the image.  Overall, well done, one of the top images in this challenge.', '2010-12-22 08:51:22.000000', NULL, 1),
(6259526, 925771, 27399, '<td valign="top">Great shot: lighting, detail, tone, composition, and subject combine perfectly in this image.</td>', 'Great shot: lighting, detail, tone, composition, and subject combine perfectly in this image.', '2010-12-22 08:53:22.000000', NULL, 1),
(6259530, 925601, 27399, '<td valign="top">The colors of the shirt mimicking the colors in the sunset is a nice touch.  Good shot overall, well done.</td>', 'The colors of the shirt mimicking the colors in the sunset is a nice touch.  Good shot overall, well done.', '2010-12-22 08:58:35.000000', NULL, 1),
(6259578, 925601, 122517, '<td valign="top">Great tones and solitude!</td>', 'Great tones and solitude!', '2010-12-22 10:23:34.000000', NULL, 1),
(6259820, 925689, 113245, '<td valign="top">Perfect.</td>', 'Perfect.', '2010-12-22 16:00:09.000000', NULL, 1),
(6259822, 925567, 113245, '<td valign="top">Very nice all around. Love the depth of field and tint. Invocative photo.</td>', 'Very nice all around. Love the depth of field and tint. Invocative photo.', '2010-12-22 16:01:19.000000', NULL, 1),
