(6259943, 925898, 93283, '<td valign="top">Interesting shot that tells a story in its simplicity... Well done! 8</td>', 'Interesting shot that tells a story in its simplicity... Well done! 8', '2010-12-22 18:51:08.000000', NULL, 1),
(6259944, 925919, 93283, '<td valign="top">I really like this shot. Great timing on the capture and the editing really makes it pop. 8</td>', 'I really like this shot. Great timing on the capture and the editing really makes it pop. 8', '2010-12-22 18:51:48.000000', NULL, 1),
