(6261758, 925766, 76335, '<td valign="top">Very low on the interest scale.</td>', 'Very low on the interest scale.', '2010-12-26 22:38:17.000000', NULL, 1),
(6261759, 925618, 76335, '<td valign="top">Good strong story, theme.</td>', 'Good strong story, theme.', '2010-12-26 22:39:10.000000', NULL, 1),
(6261760, 925501, 76335, '<td valign="top">Nice the way it tumbles into chaos as the eye wanders to the right...</td>', 'Nice the way it tumbles into chaos as the eye wanders to the right...', '2010-12-26 22:39:57.000000', NULL, 1),
(6261763, 925930, 76335, '<td valign="top">Beautifully framed. This lion roars quietly at the moment...</td>', 'Beautifully framed. This lion roars quietly at the moment...', '2010-12-26 22:41:12.000000', NULL, 1),
(6261768, 925835, 76335, '<td valign="top">Wonderful juxtapositions, great story.</td>', 'Wonderful juxtapositions, great story.', '2010-12-26 22:43:57.000000', NULL, 1),
(6261774, 925644, 76335, '<td valign="top">I do like the grain. The hotel environs are suggestive.</td>', 'I do like the grain. The hotel environs are suggestive.', '2010-12-26 22:47:43.000000', NULL, 1),
(6261777, 925848, 76335, '<td valign="top">I know who this is! Love it...</td>', 'I know who this is! Love it...', '2010-12-26 22:48:32.000000', NULL, 1),
(6261780, 925886, 76335, '<td valign="top">That''s gripping -- goes right for the heart too. It''s those hints of color -- the blue in the eyes, the red of the lips -- that make this so effective. For me anyway.</td>', 'That''s gripping -- goes right for the heart too. It''s those hints of color -- the blue in the eyes, the red of the lips -- that make this so effective. For me anyway.', '2010-12-26 22:49:54.000000', NULL, 1),
(6261781, 925567, 76335, '<td valign="top">I think straight black and white would have worked better. Or very muted colors. The sepias are too crisp and don''t quite feel right.</td>', 'I think straight black and white would have worked better. Or very muted colors. The sepias are too crisp and don''t quite feel right.', '2010-12-26 22:51:05.000000', NULL, 1),
(6261784, 925866, 76335, '<td valign="top">Very well done. Feels as though she''s about to smack that puddle and obliterate the scene.<br/><br/><br/><i>Message edited by author 2010-12-27 21:17:51.</i></td>', 'Very well done. Feels as though she''s about to smack that puddle and obliterate the scene.', '2010-12-26 22:52:49.000000', '2010-12-27 21:17:51.000000', 1),
(6261786, 925601, 76335, '<td valign="top">I do like how his shirt echoes the ripples and colors.</td>', 'I do like how his shirt echoes the ripples and colors.', '2010-12-26 22:54:26.000000', NULL, 1),
(6261789, 925887, 76335, '<td valign="top">It''s Gladys Kravitz.</td>', 'It''s Gladys Kravitz.', '2010-12-26 22:56:54.000000', NULL, 1),
(6261791, 925917, 76335, '<td valign="top">Looks like a ribbon in your near future. If not, it won''t be me who keeps you from it.</td>', 'Looks like a ribbon in your near future. If not, it won''t be me who keeps you from it.', '2010-12-26 22:57:35.000000', NULL, 1),
(6261793, 925695, 76335, '<td valign="top">Good exposure and focus, but low on intrigue.</td>', 'Good exposure and focus, but low on intrigue.', '2010-12-26 22:57:59.000000', NULL, 1),
(6261794, 925919, 76335, '<td valign="top">Flying dogs are funny. Points for you.</td>', 'Flying dogs are funny. Points for you.', '2010-12-26 22:59:35.000000', NULL, 1),
(6261795, 925884, 76335, '<td valign="top">The stage is set for something absurd to happen, but it seems that you missed it.</td>', 'The stage is set for something absurd to happen, but it seems that you missed it.', '2010-12-26 23:00:45.000000', NULL, 1),
(6261797, 925868, 76335, '<td valign="top">Early congrats on your ribbon.</td>', 'Early congrats on your ribbon.', '2010-12-26 23:01:07.000000', NULL, 1),
(6261798, 925731, 76335, '<td valign="top">Just a little bit of profile -- even a nose -- would have helped.</td>', 'Just a little bit of profile -- even a nose -- would have helped.', '2010-12-26 23:01:39.000000', NULL, 1),
(6261799, 925668, 76335, '<td valign="top">Stealthy maybe, but not very rewarding.</td>', 'Stealthy maybe, but not very rewarding.', '2010-12-26 23:03:12.000000', NULL, 1),
(6261800, 925055, 76335, '<td valign="top">Great. I like the low POV -- the man is not small but the chair somehow dominates him.</td>', 'Great. I like the low POV -- the man is not small but the chair somehow dominates him.', '2010-12-26 23:03:56.000000', NULL, 1),
(6261804, 925909, 76335, '<td valign="top">It''s the martini glass that made me do a double take and come back to throw more points at it.</td>', 'It''s the martini glass that made me do a double take and come back to throw more points at it.', '2010-12-26 23:09:34.000000', NULL, 1),
(6261808, 925325, 49916, '<td valign="top">But where are the hair? Is it a mobile image?</td>', 'But where are the hair? Is it a mobile image?', '2010-12-26 23:14:27.000000', NULL, 1),
(6261811, 925886, 49916, '<td valign="top">This is not a portrait from behind.</td>', 'This is not a portrait from behind.', '2010-12-26 23:20:03.000000', NULL, 1),
(6261815, 925857, 49916, '<td valign="top">This is from side and not behind....</td>', 'This is from side and not behind....', '2010-12-26 23:29:56.000000', NULL, 1),
(6261819, 925920, 76335, '<td valign="top">Wrong on so many levels, but spend enough time with it, and a bizarre sort of story emerges.</td>', 'Wrong on so many levels, but spend enough time with it, and a bizarre sort of story emerges.', '2010-12-26 23:43:28.000000', NULL, 1),
(6261820, 925107, 76335, '<td valign="top">Excellent. For some reason, I feel like I''m right in the studio with her.</td>', 'Excellent. For some reason, I feel like I''m right in the studio with her.', '2010-12-26 23:44:45.000000', NULL, 1),
(6261822, 925865, 76335, '<td valign="top">There''s something disorienting about this that really makes it intriguing.</td>', 'There''s something disorienting about this that really makes it intriguing.', '2010-12-26 23:45:50.000000', NULL, 1),
(6261823, 925914, 96574, '<td valign="top">there is something so magical about this shot. i''ll be shocked if this doesn''t ribbon.</td>', 'there is something so magical about this shot. i''ll be shocked if this doesn''t ribbon.', '2010-12-26 23:46:51.000000', NULL, 1),
(6261839, 925914, 52713, '<td valign="top">Very very cool. Good to see you on the front page again!</td>', 'Very very cool. Good to see you on the front page again!', '2010-12-27 00:02:30.000000', NULL, 0),
(6261840, 925914, 21304, '<td valign="top">nice - you smoked the competition on this one! had a feeling this would be a ribbon winner. awesome shot</td>', 'nice - you smoked the competition on this one! had a feeling this would be a ribbon winner. awesome shot', '2010-12-27 00:02:56.000000', NULL, 0);
